const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(x=>observer.observe(x));let ticking=false;function scrollEffects(){const max=document.documentElement.scrollHeight-innerHeight;$('.page-progress').style.width=(max>0?scrollY/max*100:0)+'%';if(!reduce&&scrollY<innerHeight&&!document.querySelector(".calm-hero")){$('.hero-image').style.transform=`translateY(${scrollY*.1}px) scale(1.015)`}ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollEffects);ticking=true}},{passive:true});scrollEffects();
let selectedTime='day';$$('[data-time]').forEach(b=>b.onclick=()=>{selectedTime=b.dataset.time;$('.hero-image').src=assets[selectedTime];$('.hero-image').alt=selectedTime==='day'?'Дневной вид комплекса Характер':'Вечерний вид комплекса Характер с тёплой подсветкой';$$('[data-time]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('.hero-index').textContent=selectedTime==='day'?'01 — 02':'02 — 02'});
const apartments=[{id:'А-021',rooms:1,area:42.6,floor:2,building:'А',terrace:false,name:'Личный ритм',description:'Отдельная спальня и кухня-гостиная.'},{id:'Б-034',rooms:1,area:51.2,floor:3,building:'Б',terrace:true,name:'Утро с небом',description:'Однокомнатная квартира с террасой.'},{id:'А-052',rooms:2,area:68.4,floor:5,building:'А',terrace:false,name:'Больше воздуха',description:'Две отдельные комнаты и кухня-гостиная.'},{id:'Б-063',rooms:2,area:79.8,floor:6,building:'Б',terrace:true,name:'Свой горизонт',description:'Две комнаты, кухня-гостиная и терраса.'},{id:'А-081',rooms:3,area:96.5,floor:8,building:'А',terrace:false,name:'Вместе и по-своему',description:'Три комнаты и общая кухня-гостиная.'},{id:'Б-092',rooms:3,area:124.3,floor:9,building:'Б',terrace:true,name:'Пространство свободы',description:'Трёхкомнатная квартира с мастер-спальней и террасой.'}];
function planSvg(a,exported=false){const roomCount=a.rooms,wide=roomCount===3?270:240;const roomWidth=(wide-30)/roomCount;let upper='';for(let n=0;n<roomCount;n++){const x=30+n*roomWidth;upper+=`<rect x="${x+10}" y="54" width="${roomWidth-20}" height="43" rx="1" fill="none" stroke="#aa9783" stroke-width="1"/><rect x="${x+13}" y="57" width="${(roomWidth-26)/2}" height="10" fill="none" stroke="#aa9783" stroke-width=".7"/><path d="M${x+roomWidth} 42v73m0 22v10" stroke="#eee7df" stroke-width="3"/><text x="${x+roomWidth/2}" y="126" text-anchor="middle" fill="#bfae9b" font-size="8">${n===0?'Спальня':'Комната'}</text>`}const terrace=a.terrace?`<path d="M30 42V15h${wide}v27" fill="#d8bfa414" stroke="#bba187" stroke-width="1" stroke-dasharray="3 3"/><text x="${30+wide/2}" y="32" text-anchor="middle" font-size="7" fill="#d5bfa4">ТЕРРАСА</text>`:'';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 ${exported?340:280}" role="img" aria-label="Иллюстративная планировка: ${roomCount} комнаты, ${a.area} квадратных метров"><rect width="330" height="${exported?340:280}" fill="${exported?'#221e1a':'transparent'}"/>${terrace}<g transform="translate(${roomCount===3?0:15},0)"><path d="M30 42h${wide}v200H160m-23 0H30V42" fill="none" stroke="#eee7df" stroke-width="4"/><path d="M30 147h${wide}M100 147v95" fill="none" stroke="#eee7df" stroke-width="3"/>${upper}<path d="M137 242v-23a23 23 0 0123 23" fill="none" stroke="#b1a18f" stroke-width="1"/><rect x="43" y="166" width="39" height="17" rx="4" fill="none" stroke="#aa9783"/><circle cx="61" cy="207" r="10" fill="none" stroke="#aa9783"/><rect x="${wide-30}" y="168" width="38" height="47" rx="2" fill="none" stroke="#aa9783"/><path d="M125 157h70v13h-70z" fill="none" stroke="#aa9783"/><rect x="145" y="190" width="40" height="22" rx="8" fill="none" stroke="#aa9783"/><text x="165" y="229" text-anchor="middle" fill="#bfae9b" font-size="7">Кухня-гостиная</text><path d="M44 42h45m30 0h45m30 0h45" stroke="#c0aa90" stroke-width="4"/><path d="M44 42h45m30 0h45m30 0h45" stroke="#221e1a" stroke-width="1"/></g>${exported?`<text x="165" y="282" text-anchor="middle" fill="#eee7df" font-size="15" font-family="Arial">ХАРАКТЕР / ${a.id} / ${a.area} м²</text><text x="165" y="303" text-anchor="middle" fill="#ac9984" font-size="8" font-family="Arial">Концепт. Планировка и размеры иллюстративные.</text>`:''}</svg>`}
let rooms='all',activeApartment=apartments[0];function renderApartments(){const list=apartments.filter(a=>(rooms==='all'||a.rooms===+rooms)&&(!$('#onlyTerrace').checked||a.terrace)).sort((a,b)=>$('#apartmentSort').value==='asc'?a.area-b.area:b.area-a.area);$('#apartmentGrid').innerHTML=list.map(a=>`<button class="apartment-card" data-apartment="${a.id}" aria-label="${a.rooms}-комнатная, ${a.area} м², ${a.name}"><div class="plan-preview"><span class="plan-tag">${a.terrace?'С ТЕРРАСОЙ':'ПАНОРАМНЫЕ ОКНА'}</span>${planSvg(a)}<span class="plan-open">+</span></div><div class="card-heading"><h3>${a.rooms}-комнатная</h3><span>${a.area.toString().replace('.',',')} м²</span></div><div class="card-info"><span>КОРПУС ${a.building} / ЭТАЖ ${a.floor}</span><span>${a.id}</span></div></button>`).join('');$('#resultCount').textContent=list.length+' '+(list.length===1?'планировка':list.length>1&&list.length<5?'планировки':'планировок');$('#emptyState').hidden=list.length>0;$$('[data-apartment]').forEach(b=>b.onclick=()=>openApartment(b.dataset.apartment))}
$$('[data-rooms]').forEach(b=>b.onclick=()=>{rooms=b.dataset.rooms;$$('[data-rooms]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',active)});renderApartments()});$('#onlyTerrace').onchange=renderApartments;$('#apartmentSort').onchange=renderApartments;$('#resetFilters').onclick=()=>{rooms='all';$('#onlyTerrace').checked=false;$('#apartmentSort').value='asc';$$('[data-rooms]').forEach(x=>{const active=x.dataset.rooms==='all';x.classList.toggle('active',active);x.setAttribute('aria-pressed',active)});renderApartments()};
function openApartment(id){activeApartment=apartments.find(a=>a.id===id);const a=activeApartment;$('#largePlan').innerHTML=planSvg(a);$('#apartmentTitle').textContent=a.name;$('#apartmentDescription').textContent=a.description;$('#apartmentSpecs').innerHTML=`<span>${a.rooms} комн.</span><span>${a.area} м²</span><span>Корпус ${a.building}</span><span>${a.floor} этаж</span><span>${a.terrace?'С террасой':'Панорамные окна'}</span>`;openDialog($('#apartmentDialog'))}
function downloadFile(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#saveApartment').onclick=()=>{downloadFile(planSvg(activeApartment,true),'image/svg+xml;charset=utf-8','character-'+activeApartment.id+'.svg');toast('Планировка сохранена')};$('#apartmentVisit').onclick=()=>{$('#apartmentDialog').close();$('#visitInterest').value=activeApartment.terrace?'Квартира с террасой':['','Однокомнатная квартира','Двухкомнатная квартира','Трёхкомнатная квартира'][activeApartment.rooms];openDialog($('#visitDialog'))};renderApartments();
const today=new Date(),dateString=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;$('#visitDate').min=dateString;$('#visitDate').value=dateString;
const icsEscape=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');$('#visitForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),date=f.get('date');if(date<dateString){toast('Выберите сегодняшнюю или будущую дату');return}const start=new Date(date+'T'+f.get('time')+':00+03:00'),end=new Date(start.getTime()+3600000),stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CHARACTER//Portfolio Concept//RU','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@character.example','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:ХАРАКТЕР — знакомство (демо)','DESCRIPTION:'+icsEscape(`${f.get('name')}, ваше приглашение для знакомства с концепцией ЖК ХАРАКТЕР. Интерес: ${f.get('interest')}. Время указано для Москвы (UTC+3). Это демонстрация: реальная встреча не назначена, данные никуда не отправлялись.`),'END:VEVENT','END:VCALENDAR'];downloadFile(lines.join('\r\n')+'\r\n','text/calendar;charset=utf-8','character-invitation.ics');$('#visitDialog').close();toast('Приглашение сохранено · время Москвы')};




